namespace HelpDeskApi.Models;

// Customer model: Represents the core data structure for a customer stored in memory
public class Customer
{
    // Unique identifier for the customer (auto-generated by the service)
    public int Id { get; set; }

    // The full name of the customer (required)
    public required string Name { get; set; }

    // The email address of the customer (required)
    public required string Email { get; set; }
}